"""Export a real game frame with HTML typography; does not retouch character models."""
import argparse,asyncio,pathlib,json
from playwright.async_api import async_playwright
p=argparse.ArgumentParser();p.add_argument('--url',default='http://127.0.0.1:4232/');p.add_argument('--out',default='artifacts/visual-review/acting-seven/share');a=p.parse_args();out=pathlib.Path(a.out);out.mkdir(parents=True,exist_ok=True)
async def main():
 async with async_playwright() as p:
  b=await p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox','--use-angle=swiftshader','--enable-unsafe-swiftshader','--disable-dev-shm-usage']);page=await b.new_page(viewport={'width':1200,'height':630},device_scale_factor=1)
  await page.goto(a.url);await page.locator('.loading-details summary').click();await page.locator('.loading-skip').click();await page.wait_for_function('window.__rainy711?.actorsLoaded&&document.querySelector("#loading").hidden',timeout=240000);await page.evaluate('__rainy711.pauseForCapture();__rainy711.missionStart()')
  for _ in range(300):
   if await page.evaluate('__rainy711.mission.phase==="walk-out"&&__rainy711.mission.shopping.handoffElapsed>=2.95'):break
   await page.evaluate('()=>{let q=__rainy711;for(let i=0;i<6;i++)q.tick(q.time+1/30,1/30,false);if(q.mission.phase==="intro")q.missionNext()}')
  assert await page.evaluate('__rainy711.mission.phase==="walk-out"')
  await page.add_style_tag(content='#app > :not(#scene){display:none!important}#scene{inset:0!important;width:100%!important}.share-cover{position:fixed;inset:0;pointer-events:none;background:linear-gradient(90deg,rgba(5,24,29,.96),rgba(5,24,29,.75) 25%,rgba(5,24,29,.08) 55%,transparent 75%);color:#eee3c5}.share-copy{position:absolute;left:66px;top:174px;width:370px}.share-eyebrow{font:18px sans-serif;letter-spacing:3px;color:#c4d1bb}.share-copy h1{font:bold 76px "Noto Serif CJK TC","Noto Serif CJK SC",serif;letter-spacing:3px;margin:20px 0 12px;color:#efdaaa;white-space:nowrap;text-shadow:0 3px 18px #0008}.share-subtitle{font:25px sans-serif;letter-spacing:6px;color:#d3deca}.share-rule{width:55px;height:2px;background:#d2bd85;margin:30px 0 22px}.share-tagline{font:22px/1.7 sans-serif;color:#c2d3c9}.share-footer{position:absolute;left:68px;bottom:47px;font:15px sans-serif;letter-spacing:2px;color:#aac3b7}.share-cover:after{content:"";position:absolute;inset:23px;border:1px solid #e0cb9138;border-radius:18px}')
  await page.evaluate('__rainy711.resetCamera()');await page.evaluate('()=>new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)))');await page.evaluate('__rainy711.tick(__rainy711.time,0,true)');await page.screenshot(path=str(out/'scene.png'))
  await page.evaluate('()=>{let e=document.createElement("div");e.className="share-cover";e.innerHTML=\'<div class="share-copy"><div class="share-eyebrow">雨夜711 · 3D 互動喜劇</div><h1>莊的晚餐</h1><div class="share-subtitle">今晚，先好好吃頓飯。</div><div class="share-rule"></div><div class="share-tagline">只是買個晚餐，<br>事情怎麼越來越不對勁？</div></div><div class="share-footer">手機・電腦　瀏覽器直接遊玩</div>\';document.body.append(e)}');await page.screenshot(path=str(out/'og-rainy711-v1.jpg'),type='jpeg',quality=90)
  (out/'source.json').write_text(json.dumps(await page.evaluate('({phase:__rainy711.mission.phase,age:__rainy711.mission.shopping.handoffElapsed,meal:__rainy711.mission.branch,camera:__rainy711.cameraPose})'),ensure_ascii=False,indent=2))
  await page.set_viewport_size({'width':180,'height':180});await page.set_content('<style>html,body{margin:0;width:180px;height:180px;background:#142b32}img{display:block;width:180px;height:180px}</style><img src="'+a.url.rstrip('/')+'/favicon.svg">');await page.locator('img').evaluate('e=>e.decode()');await page.screenshot(path=str(out/'apple-touch-icon.png'));await b.close()
asyncio.run(main())
